            {
                switch (index % 4)
                {
                    case 1: return Get("Car_Traffic_E30_Paint_DeepBlue");
                    case 2: return Get("Car_Traffic_E30_Paint_Black");
                    case 3: return Get("Car_Traffic_E30_Paint_Silver");
                }
