            if (glb == TeslaGlb && (sourceName == "PaletteMaterial002" || sourceName == "primary.001" || sourceName == "primary.002"))
            {
                switch (index % 3)
                {
                    case 1: return Get("Car_Traffic_Tesla_Paint_MidnightSilver");
